/**
 * アイコン1つぶんの HTML。
 * @param nm    `fa-cog` のような名前。**空文字なら空を返す**（アイコン無しの項目用）
 * @param extra 追加のクラス
 */
export function faSvg(nm: string, extra = ''): string {
	if (! nm) return '';

	const o = H_FA_ICON[nm.replace(/^fa-/, '')];
	if (! o) {console.error(`fn:faIcon.ts 未収録のアイコン ${nm}`); return ''}

	return `<svg class="fa-i${extra ? ' '+ extra : ''}" viewBox="${o[0]}" aria-hidden="true"><path d="${o[1]}"/></svg>`;
}
